  let user = null, currentRoom = null, roomChannel = null, unreadChannel = null, unreadChannelUser = '', friendPresenceChannel=null,friendPresenceUserId='',friendSearchTimer=null,profilePreviewPerson=null,unreadRefreshTimer = null, rooms = [], roomAssets = [], friendsData=[], incomingFriendRequests=[], blockedUserIds = new Set(), typingTimer = null, toastTimer = null, sentTyping = 0, currentDay = '', unreadMessageId = null, lastMessageAt = '', lastReadAt = '', readSaveTimer = null, replyingTo = null, searchTimer = null, searchContext = false, unreadCounts = new Map();
  const reactionChoices=['👍','❤️','😂','😮','😢','🎉'],reactionCache=new Map();
