  function renderRoomLogo(container,room){container.replaceChildren();if(room?.logo_url){const image=document.createElement('img');image.src=room.logo_url;image.alt=`${room.name} logo`;container.append(image)}else container.textContent=room?.is_private?'⌑':'#'}
  async function getRoomLogoUrl(path){if(!path)return '';const {data,error}=await db.storage.from('room-assets').createSignedUrl(path,86400);return error?'':data?.signedUrl||''}
  async function refreshRoomLogo(roomId,path){const url=await getRoomLogoUrl(path),room=rooms.find(item=>item.id===roomId);if(room){room.logo_path=path;room.logo_url=url}if(currentRoom?.id===roomId){currentRoom.logo_path=path;currentRoom.logo_url=url;renderRoomLogo($('roomSymbol'),currentRoom)}renderRooms()}
  async function saveRoomDetails(event){event.preventDefault();if(!currentRoom||currentRoom.created_by!==user?.id){setFeedback('roomDetailsFeedback','Only the room owner can edit these details.');return}const name=escapeRoomName($('roomDetailsName').value),description=$('roomDetailsDescription').value.trim()||null;if(!name){setFeedback('roomDetailsFeedback','Enter a room name using letters or numbers.');$('roomDetailsName').focus();return}const roomId=currentRoom.id,button=$('saveRoomDetailsButton'),previous={name:currentRoom.name,description:currentRoom.description};button.disabled=true;setFeedback('roomDetailsFeedback','Saving room details…');try{const {data,error}=await db.from('rooms').update({name,description}).eq('id',roomId).eq('created_by',user.id).select('id').maybeSingle();if(error)throw error;if(!data)throw new Error('The room owner policy did not allow this update.');currentRoom.name=name;currentRoom.description=description;const room=rooms.find(item=>item.id===roomId);if(room){room.name=name;room.description=description}ui.currentRoomName.textContent=name;$('roomHeading').textContent=name;$('roomDescription').textContent=description||'A place to talk.';renderRoomLogo($('roomSymbol'),currentRoom);renderRoomLogo($('roomLogoPreview'),currentRoom);renderRooms();setFeedback('roomDetailsFeedback','Room details saved.',true);notify('Room details saved.')}catch(error){currentRoom.name=previous.name;currentRoom.description=previous.description;setFeedback('roomDetailsFeedback',`Could not save room details: ${error.message||'Please try again.'}`);notify(`Could not save room details: ${error.message||'Please try again.'}`)}finally{button.disabled=false}}
  function paintInviteExpiry(room){$('roomInviteSettings').classList.toggle('hidden',!room?.is_private);const expiry=room?.invite_expires_at?new Date(room.invite_expires_at):null;$('inviteExpiryStatus').textContent=expiry?`Expires ${expiry.toLocaleString()}`:'Links do not expire';if(!expiry){$('inviteExpiryChoice').value='never';return}const remaining=expiry.getTime()-Date.now();const options=[['1h',3600000],['24h',86400000],['7d',604800000],['30d',2592000000]],nearest=options.find(([,duration])=>Math.abs(remaining-duration)<duration*.2);$('inviteExpiryChoice').value=nearest?.[0]||'never'}
  async function saveRoomInvite(event){event.preventDefault();if(!currentRoom?.is_private||currentRoom.created_by!==user?.id){setFeedback('roomInviteFeedback','Only the room owner can manage private invite links.');return}const choice=$('inviteExpiryChoice').value,durations={ '1h':3600000,'24h':86400000,'7d':604800000,'30d':2592000000},inviteCode=crypto.randomUUID().replaceAll('-',''),expiresAt=durations[choice]?new Date(Date.now()+durations[choice]).toISOString():null,button=$('saveRoomInviteButton'),roomId=currentRoom.id;button.disabled=true;setFeedback('roomInviteFeedback','Updating invite link…');try{const {data,error}=await db.from('rooms').update({invite_code:inviteCode,invite_expires_at:expiresAt}).eq('id',roomId).eq('created_by',user.id).select('id').maybeSingle();if(error)throw error;if(!data)throw new Error('The room owner policy did not allow this update.');currentRoom.invite_code=inviteCode;currentRoom.invite_expires_at=expiresAt;const room=rooms.find(item=>item.id===roomId);if(room){room.invite_code=inviteCode;room.invite_expires_at=expiresAt}paintInviteExpiry(currentRoom);setFeedback('roomInviteFeedback','Invite link updated. Copy it from the room link button.',true);notify('Invite link updated. The previous link is no longer valid.')}catch(error){setFeedback('roomInviteFeedback',`Could not update invite: ${error.message||'Please try again.'}`);notify(`Could not update invite: ${error.message||'Please try again.'}`)}finally{button.disabled=false}}
  async function saveRoomLogo(){if(!currentRoom||currentRoom.created_by!==user?.id){setFeedback('roomLogoFeedback','Only the room owner can change the room logo.');return}const file=$('roomLogoFile').files?.[0];if(!file){setFeedback('roomLogoFeedback','Choose an image first.');return}if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>2*1024*1024){setFeedback('roomLogoFeedback','Choose a PNG, JPG, or WebP image up to 2 MB.');return}const roomId=currentRoom.id,oldPath=currentRoom.logo_path||'',ext=file.type==='image/jpeg'?'jpg':file.type.split('/')[1],path=`${roomId}/logo/${crypto.randomUUID()}.${ext}`,button=$('saveRoomLogoButton');button.disabled=true;setFeedback('roomLogoFeedback','Uploading logo…');try{const {error:uploadError}=await db.storage.from('room-assets').upload(path,file,{contentType:file.type,cacheControl:'3600',upsert:false});if(uploadError)throw uploadError;const {data,error}=await db.from('rooms').update({logo_path:path}).eq('id',roomId).eq('created_by',user.id).select('id').maybeSingle();if(error||!data){await db.storage.from('room-assets').remove([path]);throw error||new Error('The room owner policy did not allow this update.')}currentRoom.logo_path=path;currentRoom.logo_url=await getRoomLogoUrl(path);const room=rooms.find(item=>item.id===roomId);if(room){room.logo_path=path;room.logo_url=currentRoom.logo_url}renderRoomLogo($('roomSymbol'),currentRoom);renderRoomLogo($('roomLogoPreview'),currentRoom);renderRooms();if(oldPath)await db.storage.from('room-assets').remove([oldPath]);$('roomLogoFile').value='';$('removeRoomLogoButton').classList.remove('hidden');setFeedback('roomLogoFeedback','Room logo saved.',true);notify('Room logo saved.')}catch(error){setFeedback('roomLogoFeedback',`Could not save logo: ${error.message||'Please try again.'}`);notify(`Could not save logo: ${error.message||'Please try again.'}`)}finally{button.disabled=false}}
  async function removeRoomLogo(){if(!currentRoom||currentRoom.created_by!==user?.id||!currentRoom.logo_path)return;const roomId=currentRoom.id,path=currentRoom.logo_path;const {error}=await db.from('rooms').update({logo_path:null}).eq('id',roomId).eq('created_by',user.id);if(error){setFeedback('roomLogoFeedback',`Could not remove logo: ${error.message}`);notify(`Could not remove logo: ${error.message}`);return}currentRoom.logo_path=null;currentRoom.logo_url='';const room=rooms.find(item=>item.id===roomId);if(room){room.logo_path=null;room.logo_url=''}renderRoomLogo($('roomSymbol'),currentRoom);renderRoomLogo($('roomLogoPreview'),currentRoom);renderRooms();await db.storage.from('room-assets').remove([path]);$('removeRoomLogoButton').classList.add('hidden');setFeedback('roomLogoFeedback','Room logo removed.',true);notify('Room logo removed.')}
