  async function loadRoomAssets(roomId){const {data,error}=await db.from('room_assets').select('id,room_id,kind,name,object_path,created_by').eq('room_id',roomId).order('created_at',{ascending:true});if(error){roomAssets=[];renderAssetLists();notify(`Could not load room emoji and stickers: ${error.message}`);return false}roomAssets=await Promise.all((data||[]).map(async asset=>{const {data:signed,error:signedError}=await db.storage.from('room-assets').createSignedUrl(asset.object_path,86400);return {...asset,url:signedError?'':signed?.signedUrl||''}}));renderAssetLists();return true}
