  async function addRoomAsset(kind,nameInput,fileInput,feedbackId,form){if(!currentRoom||currentRoom.created_by!==user?.id){setFeedback(feedbackId,'Only the room owner can add assets.');return}const name=$(nameInput).value.trim().toLowerCase().replace(/[^a-z0-9_-]+/g,'-').replace(/^-+|-+$/g,'').slice(0,24),file=$(fileInput).files?.[0],existing=roomAssets.filter(a=>a.kind===kind).length;setFeedback(feedbackId,'');if(!/^[a-z0-9_-]{1,24}$/.test(name)){setFeedback(feedbackId,'Use 1–24 lowercase letters, numbers, hyphens, or underscores.');return}if(!file){setFeedback(feedbackId,'Choose an image first.');return}if(!['image/png','image/jpeg','image/webp','image/gif'].includes(file.type)||file.size>2*1024*1024){setFeedback(feedbackId,'Choose a PNG, JPG, WebP, or GIF image up to 2 MB.');return}if(existing>=(kind==='emoji'?50:10)){setFeedback(feedbackId,`This room has reached its ${kind==='emoji'?50:10} ${kind} limit.`);return}const submit=form?.querySelector('button[id^="add"]');if(submit)submit.disabled=true;const roomId=currentRoom.id,ext=file.type==='image/jpeg'?'jpg':file.type.split('/')[1],path=`${roomId}/${kind}/${crypto.randomUUID()}.${ext}`;setFeedback(feedbackId,'Uploading image…');try{const {error:uploadError}=await db.storage.from('room-assets').upload(path,file,{contentType:file.type,cacheControl:'3600',upsert:false});if(uploadError)throw uploadError;setFeedback(feedbackId,'Saving asset to this room…');const {error:insertError}=await db.from('room_assets').insert({room_id:roomId,kind,name,object_path:path,created_by:user.id});if(insertError){await db.storage.from('room-assets').remove([path]);throw insertError}$(nameInput).value='';$(fileInput).value='';const refreshed=await loadRoomAssets(roomId);setFeedback(feedbackId,refreshed?`${kind==='emoji'?'Emoji':'Sticker'} added.`:'Saved, but the list could not refresh. Reopen the room manager.',true)}catch(error){setFeedback(feedbackId,`Could not add ${kind}: ${error.message||'Please try again.'}`)}finally{if(submit)submit.disabled=false}}
  async function removeRoomAsset(asset){if(!currentRoom||currentRoom.created_by!==user?.id)return;if(!confirm(`Remove ${asset.kind} “${asset.name}” from this room?`))return;const {error}=await db.from('room_assets').delete().eq('id',asset.id);if(error){notify(`Could not remove asset: ${error.message}`);return}await db.storage.from('room-assets').remove([asset.object_path]);await loadRoomAssets(currentRoom.id)}
  function dateLabel(date){return new Intl.DateTimeFormat(undefined,{weekday:'long',month:'long',day:'numeric'}).format(date)}
