  function renderReactionBar(messageId){const row=ui.stream.querySelector(`[data-message-id="${CSS.escape(messageId)}"]`);if(!row)return;let bar=row.querySelector('.message-reactions');if(!bar){bar=document.createElement('div');bar.className='message-reactions';row.querySelector('.message-body').append(bar)}bar.replaceChildren();const items=reactionCache.get(messageId)||[];const groups=new Map();items.forEach(item=>{const group=groups.get(item.emoji)||{count:0,mine:false};group.count++;group.mine||=item.user_id===user?.id;groups.set(item.emoji,group)});groups.forEach((group,emoji)=>{const button=document.createElement('button');button.type='button';button.className='reaction-chip'+(group.mine?' mine':'');button.textContent=`${emoji} ${group.count}`;button.setAttribute('aria-label',`${group.count} ${emoji} reaction${group.count===1?'':'s'}${group.mine?', including yours':''}`);button.addEventListener('click',()=>toggleReaction(messageId,emoji,group.mine));bar.append(button)})}
