  async function loadMessageReactions(messageIds){const ids=[...new Set(messageIds)].filter(Boolean);for(let index=0;index<ids.length;index+=80){const batch=ids.slice(index,index+80),{data,error}=await db.from('message_reactions').select('message_id,user_id,emoji').in('message_id',batch);if(error){notify(`Could not load reactions: ${error.message}`);return}(data||[]).forEach(item=>{const group=reactionCache.get(item.message_id)||[];group.push(item);reactionCache.set(item.message_id,group)})}ids.forEach(renderReactionBar)}
