  async function openMediaPreview(path,type){if(!path)return;previewAttachment={path,type};const stage=$('mediaPreviewStage'),dialog=$('mediaPreviewDialog');stage.replaceChildren();const {data,error}=await db.storage.from('room-assets').createSignedUrl(path,86400);if(error||!data?.signedUrl){notify(`Could not open attachment: ${error?.message||'Please try again.'}`);return}const media=type==='video'?document.createElement('video'):document.createElement('img');media.src=data.signedUrl;if(type==='video'){media.controls=true;media.autoplay=true;media.playsInline=true}else{media.alt='Image attachment'}stage.append(media);if(!dialog.open)dialog.showModal()}
