    const avatar=document.createElement('button');avatar.type='button';avatar.className='avatar message-avatar profile-trigger';avatar.setAttribute('aria-label',`View ${message.author_name||'user'}'s profile`);setAvatar(avatar,message.author_name||'Someone',message.author_avatar_url);avatar.addEventListener('click',()=>openUserProfile({user_id:message.user_id,name:message.author_name,avatar_url:message.author_avatar_url}));
    const body=document.createElement('div');body.className='message-body';const meta=document.createElement('div');meta.className='message-meta';const name=document.createElement('button');name.type='button';name.className='message-author-button profile-trigger';name.textContent=message.author_name||'Someone';name.addEventListener('click',()=>openUserProfile({user_id:message.user_id,name:message.author_name,avatar_url:message.author_avatar_url}));const time=document.createElement('time');time.dateTime=date.toISOString();time.textContent=timeLabel(date);meta.append(name,time);
    body.append(meta);
    if(message.reply_author_name||message.reply_excerpt){const quote=document.createElement(message.reply_to?'button':'div');quote.className='message-reply-preview';if(message.reply_to){quote.type='button';quote.addEventListener('click',()=>scrollToMessage(message.reply_to))}const author=document.createElement('strong');author.textContent=message.reply_author_name||'Someone';const excerpt=document.createElement('span');excerpt.textContent=message.reply_excerpt||'Message';quote.append(author,excerpt);body.append(quote)}
    if(message.message_type==='sticker'){const sticker=document.createElement('div');sticker.className='message-sticker';const asset=roomAssets.find(a=>a.id===message.asset_id);if(asset?.url){const image=document.createElement('img');image.src=asset.url;image.alt=asset.name;sticker.append(image)}else{const missing=document.createElement('span');missing.className='message-sticker-unavailable';missing.textContent='Sticker unavailable';sticker.append(missing)}body.append(sticker)}else if(message.message_type==='image'||message.message_type==='video'){const media=document.createElement('div');media.className='message-media previewable';media.setAttribute('role','button');media.tabIndex=0;media.setAttribute('aria-label',`Open ${message.message_type} preview`);media.addEventListener('click',()=>openMediaPreview(message.media_path,message.message_type));media.addEventListener('keydown',event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();openMediaPreview(message.media_path,message.message_type)}});const placeholder=document.createElement('span');placeholder.className='message-sticker-unavailable';placeholder.textContent='Loading attachment…';media.append(placeholder);body.append(media);if(message.media_path)db.storage.from('room-assets').createSignedUrl(message.media_path,86400).then(({data,error})=>{if(!row.isConnected)return;media.replaceChildren();if(error||!data?.signedUrl){placeholder.textContent='Attachment unavailable';media.append(placeholder);return}if(message.message_type==='video'){media.classList.add('video-previewable');const video=document.createElement('video');video.src=data.signedUrl;video.preload='metadata';video.playsInline=true;video.setAttribute('aria-label','Click to preview video');media.append(video)}else{const image=document.createElement('img');image.src=data.signedUrl;image.alt='Click to preview image';image.loading='lazy';media.append(image)}}).catch(()=>{placeholder.textContent='Attachment unavailable'})}else{const text=document.createElement('div');text.className='message-text';renderMessageContent(text,message.content);body.append(text)}
    const actions=document.createElement('span');actions.className='message-actions';const reply=document.createElement('button');reply.type='button';reply.textContent='reply';reply.setAttribute('aria-label',`Reply to ${message.author_name||'message'}`);reply.addEventListener('click',()=>setReplyTarget(message));actions.append(reply);const react=document.createElement('button');react.type='button';react.textContent='react';react.setAttribute('aria-label','Add a reaction');react.addEventListener('click',()=>toggleReactionPicker(row,message));actions.append(react);if(message.user_id!==user?.id){const report=document.createElement('button');report.type='button';report.textContent='report';report.setAttribute('aria-label',`Report ${message.author_name||'this'}'s message`);report.addEventListener('click',()=>reportMessage(message));actions.append(report)}if(message.user_id===user?.id){if(message.message_type==='text'){const edit=document.createElement('button');edit.type='button';edit.textContent='edit';edit.setAttribute('aria-label','Edit your message');edit.addEventListener('click',()=>editMessage(message));actions.append(edit)}const del=document.createElement('button');del.type='button';del.textContent='delete';del.setAttribute('aria-label','Delete your message');del.addEventListener('click',()=>deleteMessage(message.id));actions.append(del)}meta.append(actions);
