  function renderMessageContent(node,content){node.replaceChildren();const pattern=/:([a-z0-9_-]{1,24}):/gi;let cursor=0,match;while((match=pattern.exec(content))){node.append(document.createTextNode(content.slice(cursor,match.index)));const asset=roomAssets.find(a=>a.kind==='emoji'&&a.name===match[1].toLowerCase());if(asset?.url){const img=document.createElement('img');img.className='inline-custom-emoji';img.src=asset.url;img.alt=match[0];img.title=match[0];node.append(img)}else node.append(document.createTextNode(match[0]));cursor=pattern.lastIndex}node.append(document.createTextNode(content.slice(cursor)));node.classList.toggle('has-custom-emoji',!!node.querySelector('.inline-custom-emoji'))}
