  function renderSearchResults(results,query){const box=$('roomSearchResults');box.replaceChildren();box.classList.remove('hidden');results=results.filter(result=>!blockedUserIds.has(result.user_id));if(!results.length){const empty=document.createElement('div');empty.className='room-search-empty';empty.textContent=`No messages found for “${query}”.`;box.append(empty);return}const count=document.createElement('div');count.className='room-search-count';count.textContent=`Showing ${results.length} recent match${results.length===1?'':'es'}`;box.append(count);results.forEach(result=>{const button=document.createElement('button');button.type='button';button.className='room-search-result';button.setAttribute('role','option');const meta=document.createElement('span');meta.className='room-search-result-meta';const author=document.createElement('strong');author.textContent=result.author_name||'Someone';const time=document.createElement('time');time.dateTime=result.created_at;time.textContent=timeLabel(new Date(result.created_at));meta.append(author,time);const content=document.createElement('span');content.className='room-search-result-content';content.textContent=result.message_type==='sticker'?'Sticker':result.content||'';button.append(meta,content);button.addEventListener('click',()=>openSearchResult(result));box.append(button)})}
