  $('inviteButton').addEventListener('click',async()=>{if(!currentRoom){notify('Open a room first to invite your people.');return}if(currentRoom.is_private&&currentRoom.invite_expires_at&&new Date(currentRoom.invite_expires_at).getTime()<=Date.now()){notify('This invite link expired. Open room settings to create a fresh one.');return}const url=currentRoom.is_private?`${location.origin}${location.pathname}?invite=${encodeURIComponent(currentRoom.invite_code)}`:`${location.origin}${location.pathname}?room=${encodeURIComponent(currentRoom.id)}`;try{await navigator.clipboard.writeText(url);notify('Room link copied.')}catch{prompt('Copy this room link',url)}});
  $('roomSearch').addEventListener('input',()=>{const box=$('publicRoomSearch');box.value=$('roomSearch').value;renderRooms()});$('publicRoomSearch').addEventListener('input',()=>{ $('roomSearch').value=$('publicRoomSearch').value;renderRooms()});
  $('peopleInfo').addEventListener('click',()=>notify('People in the list are here right now.'));$('roomReportsToggle').addEventListener('click',()=>showRoomReports(true));$('backToPeople').addEventListener('click',()=>showRoomReports(false));$('roomRestrictionsToggle').addEventListener('click',()=>showRoomRestrictions(true));$('backToPeopleFromRestrictions').addEventListener('click',()=>showRoomRestrictions(false));$('mobileMenu').addEventListener('click',()=>toggleMobileDrawer('rooms'));$('mobilePeopleButton').addEventListener('click',()=>toggleMobileDrawer('people'));$('mobileDrawerBackdrop').addEventListener('click',()=>closeMobileDrawers(true));$('closePeoplePanel').addEventListener('click',()=>closeMobileDrawers(true));document.addEventListener('keydown',event=>{if(event.key==='Escape'){closeMobileDrawers(true);return}if(event.key!=='Tab')return;const drawer=$('sidebar').classList.contains('open')?$('sidebar'):$('peoplePanel').classList.contains('open')?$('peoplePanel'):null;if(!drawer)return;const focusable=[...drawer.querySelectorAll('a[href],button:not(:disabled),input:not(:disabled),[tabindex]:not([tabindex="-1"])')].filter(node=>!node.classList.contains('hidden')&&node.getClientRects().length);if(!focusable.length)return;const first=focusable[0],last=focusable.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus()}});document.addEventListener('click',event=>{if(event.target.closest('.room-item'))closeMobileDrawers()});
  $('friendsNavButton').addEventListener('click',showFriendsView);$('friendSearchInput').addEventListener('input',()=>{clearTimeout(friendSearchTimer);friendSearchTimer=setTimeout(searchFriends,250)});$('profileFriendAction').addEventListener('click',handleProfileFriendAction);$('closeUserProfile').addEventListener('click',()=>$('userProfileDialog').close());$('userProfileDialog').addEventListener('click',event=>{if(event.target===$('userProfileDialog'))$('userProfileDialog').close()});$('userProfileDialog').addEventListener('close',()=>{profilePreviewPerson=null;$('profileFriendAction').dataset.relationship='';$('profileFriendAction').dataset.requestId=''});

  renderProfile();
